function quotePdfRoot(){return (getenv('ERP_PROFORMA_FILES_ROOT') ?: (PHP_OS_FAMILY==='Windows'?'C:/xampp/accounting-private/proforma-attachments':dirname(__DIR__,2).'/private/proforma-attachments')).'/quotes';}
try{
 if(isset($_GET['token'])){$token=(string)$_GET['token'];if(!preg_match('/^[a-f0-9]{64}$/D',$token)||!is_file(quotePdfRoot().'/'.$token.'.pdf'))quotePdfFail(404,'Proforma no disponible.');$file=quotePdfRoot().'/'.$token.'.pdf';header('Content-Type: application/pdf');header('Content-Disposition: attachment; filename="proforma.pdf"');header('Content-Length: '.filesize($file));readfile($file);exit;}
 session_start();if(empty($_SESSION['user'])||(isset($_SESSION['expire'])&&$_SESSION['expire']<time()))quotePdfFail(401,'Inicia sesión nuevamente.');$db=appPdoConnection();$db->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$s=$db->prepare('SELECT IdUsuarioPerfil FROM Seg_Usuario WHERE Usuario=? AND COALESCE(Anulado,0)=0');$s->execute([$_SESSION['user']]);if(!$s->fetchColumn())quotePdfFail(403,'Usuario no autorizado.');session_write_close();
