 $s=$db->prepare('SELECT p.*,c.Cliente,c.DniRuc AS Documento,c.Direccion AS ClienteDireccion,c.Telefono AS ClienteTelefono FROM Ve_Proforma p JOIN Ve_DocVentaCliente c ON c.IdCliente=p.IdCliente WHERE p.IdProforma=? AND COALESCE(p.Anulado,0)=0');$s->execute([$id]);$quote=$s->fetch(PDO::FETCH_ASSOC);if(!$quote)quotePdfFail(404,'Proforma no disponible.');
 $s=$db->prepare('SELECT d.Cantidad,d.Precio,d.Descuento,d.DisabledTotal,d.Descripcion,g.Imagen,g.Producto,g.ProductoDesc,g.ProductoDesc2,g.ProductoDesc3 FROM Ve_ProformaDet d JOIN Gen_Producto g ON g.IdProducto=d.IdProducto WHERE d.IdProforma=?');$s->execute([$id]);$products=$s->fetchAll(PDO::FETCH_ASSOC);
