 $root=quotePdfRoot();if(!is_dir($root)&&!mkdir($root,0700,true))throw new RuntimeException('Cannot create PDF directory');$token=bin2hex(random_bytes(32));$file=$root.'/'.$token.'.pdf';if(file_put_contents($file,$data,LOCK_EX)!==strlen($data))throw new RuntimeException('Cannot save PDF');@chmod($file,0600);header('Content-Type: application/json; charset=utf-8');echo json_encode(['url'=>'/api/proforma-pdf.php?token='.$token]);
